Contract GenerateLoanLetterAndAgreementModule::createLoanAccount(loanaccountid:Integer,balance:Real,status:LoanAccountStatus[NORMAL|HASPAIDINFULL]): Boolean {
          definition:
          la:LoanAccount = LoanAccount.allInstance()->any(o | o.LoanAccountID = loanaccountid), laNotExist:Boolean = if la.oclIsUndefined() then true else false endif


            postcondition:
          if laNotExist then let newLa:LoanAccount in newLa.oclIsNew() and LoanAccount.allInstance()->includes(newLa) and newLa.LoanAccountID = loanaccountid and newLa.Balance = balance and newLa.Status = status and result = laNotExist else result = laNotExist endif

        }
